public String removeDuplicates(String s) {
    StringBuilder sb = new StringBuilder();
    java.util.Set<Character> seen = new java.util.HashSet<>();
    for (char ch : s.toCharArray()) {
        if (seen.add(ch)) sb.append(ch);
    }
    return sb.toString();
}

